<?php declare(strict_types=1);namespace StudPulse\Integrations;use DateTimeImmutable;use DateTimeZone;use StudPulse\Bars\ProviderResult;use StudPulse\Config;use StudPulse\Http\ApiError;final class MpeiSchedule{private const API='https://ts.mpei.ru/api';private const SOURCE='РУЗ МЭИ';public static function forGroup(string$group,string$from,string$to):ProviderResult{$group=trim($group);if(!preg_match('/^[\p{L}\p{N} .\-‐‑–—]{2,40}$/uD',$group)){throw new ApiError(403,'RUZ_GROUP_REQUIRED','Для расписания нужна учебная группа из профиля МЭИ.');}return self::schedule('group',$group,$from,$to);}public static function forTeacher(string$teacher,string$from,string$to):ProviderResult{$parts=self::nameParts($teacher);if(count($parts)<2||count($parts)>3){throw new ApiError(422,'RUZ_TEACHER_NAME','РУЗ не распознал имя преподавателя.');}return self::schedule('person',$teacher,$from,$to);}private static function schedule(string$type,string$name,string$from,string$to):ProviderResult{$moscow=new DateTimeZone('Europe/Moscow');$utc=new DateTimeZone('UTC');$start=new DateTimeImmutable($from,$utc);$end=new DateTimeImmutable($to,$utc);$first=$start->setTimezone($moscow)->modify('monday this week');$last=$end->modify('-1 second')->setTimezone($moscow)->modify('sunday this week');$person=$type==='person';$key=($person?'person:'.implode(' ',self::nameParts($name)):self::groupKey($name)).':'.$first->format('Y-m-d').':'.$last->format('Y-m-d');$cache=self::cache($key);$stale=false;if(!$cache||time()-$cache['at']>300){try{[$id,$label]=$person?self::teacherId($name):[self::groupId($name),$name];$rows=self::get('/schedule/'.$type.'/'.$id,['start'=>$first->format('Y.m.d'),'finish'=>$last->format('Y.m.d'),'lng'=>1,]);$cache=['at'=>time(),'items'=>self::lessons($rows,$label,$person),'label'=>$label];self::cache($key,$cache);}catch(ApiError$error){if(!$cache||time()-$cache['at']>86400){throw$error;}$stale=true;}}$items=array_values(array_filter($cache['items'],static fn(array$lesson):bool=>$lesson['start_at']>=$from&&$lesson['start_at']<$to));return new ProviderResult($items,self::SOURCE,gmdate('c',$cache['at']),false,[($person?'teacher':'group')=>$cache['label']??$name,'stale'=>$stale,]);}private static function nameParts(string$name):array{$name=preg_replace('/^(?:(?:ст\.\s*преп\.|преп\.|доц\.|ассист\.|проф\.|профессор|доцент|ассистент)\s*)+/ui','',trim($name));preg_match_all('/\p{L}+(?:-\p{L}+)?/u',str_replace('ё','е',mb_strtolower($name)),$words);return$words[0];}public static function sameTeacher(string$left,string$right):bool{$a=self::nameParts($left);$b=self::nameParts($right);if(count($a)<2||count($a)!==count($b)||$a[0]!==$b[0])return false;foreach(array_slice($a,1,null,true)as$i=>$part){if($part!==$b[$i]&&!((mb_strlen($part)===1||mb_strlen($b[$i])===1)&&mb_substr($part,0,1)===mb_substr($b[$i],0,1)))return false;}return true;}public static function teacherSurname(string$name):string{return self::nameParts($name)[0]??'';}private static function teacherId(string$name):array{$wanted=self::nameParts($name);$matches=[];foreach(self::get('/search',['term'=>$wanted[0],'type'=>'person'])as$row){if(!is_array($row)||($row['type']??'person')!=='person'||!is_string($row['label']??null)){continue;}$candidate=self::nameParts($row['label']);$id=filter_var($row['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false||count($candidate)<count($wanted)||$candidate[0]!==$wanted[0]){continue;}foreach(array_slice($wanted,1,null,true)as$i=>$part){if($part!==$candidate[$i]&&!((mb_strlen($part)===1||mb_strlen($candidate[$i])===1)&&mb_substr($part,0,1)===mb_substr($candidate[$i],0,1))){continue 2;}}$matches[$id]=[$id,$row['label']];}if(count($matches)!==1){throw new ApiError(422,'RUZ_TEACHER_AMBIGUOUS','В РУЗ нет однозначного совпадения для этого преподавателя.');}return reset($matches);}private static function groupId(string$group):int{$key='group:'.self::groupKey($group);$cached=self::cache($key);if($cached&&time()-$cached['at']<86400){return$cached['items'][0];}$rows=self::get('/search',['term'=>$group,'type'=>'group']);$matches=[];foreach($rows as$row){if(!is_array($row)||($row['type']??'group')!=='group'||!is_string($row['label']??null)){continue;}$id=filter_var($row['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id!==false&&self::groupKey($row['label'])===self::groupKey($group)){$matches[$id]=$id;}}if(count($matches)!==1){throw new ApiError(404,'RUZ_GROUP_NOT_FOUND','В РУЗ МЭИ не нашлось однозначного расписания для группы '.$group.'.');}$id=reset($matches);self::cache($key,['at'=>time(),'items'=>[$id]]);return$id;}private static function get(string$path,array$query):array{try{$response=HttpClient::request('GET',self::API.$path.'?'.http_build_query($query,'','&',PHP_QUERY_RFC3986),['Accept: application/json']);}catch(ApiError){throw new ApiError(502,'RUZ_UNAVAILABLE','РУЗ МЭИ сейчас не ответил. Попробуйте обновить расписание.');}if(!is_array($response['json'])||!array_is_list($response['json'])){throw new ApiError(502,'RUZ_FORMAT','РУЗ МЭИ вернул расписание в неизвестном формате.');}return$response['json'];}public static function lessons(array$rows,string$group,bool$person=false):array{$moscow=new DateTimeZone('Europe/Moscow');$utc=new DateTimeZone('UTC');$observedAt=gmdate('Y-m-d H:i:s');$items=[];foreach($rows as$row){if(!is_array($row)){continue;}$date=str_replace('.','-',self::field($row,'date'));$begin=$date.' '.self::field($row,'beginLesson');$finish=$date.' '.self::field($row,'endLesson');if(!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/D',$begin)||!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/D',$finish)){continue;}$start=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$begin,$moscow);$end=DateTimeImmutable::createFromFormat('!Y-m-d H:i',$finish,$moscow);$title=self::field($row,'discipline');if(!$start||!$end||$start->format('Y-m-d H:i')!==$begin||$end->format('Y-m-d H:i')!==$finish||$end<=$start||$title===''){continue;}$teacher=self::field($row,'lecturer');$room=self::field($row,'auditorium');$type=self::field($row,'kindOfWork');$subgroup=is_int($row['subGroup']??null)?(string)$row['subGroup']:self::field($row,'subGroup');$groupName=$person?(self::field($row,'stream')?:self::field($row,'group')):'';$parts=[self::groupKey($group),$begin,$finish,$title,$type,$teacher,$room,$subgroup];$id=hash('sha256',implode('|',$person?[...$parts,$groupName]:$parts));$items[$id]=['id'=>$id,'subject_id'=>null,'subject_title'=>$title,'start_at'=>$start->setTimezone($utc)->format('Y-m-d H:i:s'),'end_at'=>$end->setTimezone($utc)->format('Y-m-d H:i:s'),'class_type'=>$type,'teacher_id'=>null,'teacher_name'=>$teacher,'teacher_full_name'=>self::field($row,'lecturer_title'),'room_id'=>null,'official_room_code'=>$room,'subgroup_id'=>null,'subgroup_name'=>$subgroup,'group_name'=>$groupName,'source'=>'ruz','status'=>'scheduled','revision'=>1,'last_synced_at'=>$observedAt,];}if($rows&&!$items){throw new ApiError(502,'RUZ_FORMAT','Не удалось прочитать даты и время занятий из РУЗ МЭИ.');}usort($items,static fn(array$left,array$right):int=>[$left['start_at'],$left['id']]<=>[$right['start_at'],$right['id']]);return$items;}public static function groupKey(string$group):string{return mb_strtoupper(preg_replace('/[\s\-‐‑–—]+/u','',$group)??$group);}private static function field(array$row,string$key):string{return is_string($row[$key]??null)?trim($row[$key]):'';}private static function cache(string$key,?array$value=null):?array{$directory=Config::storage().'/ruz';$path=$directory.'/'.hash('sha256','v2:'.$key).'.json';if($value!==null){if(!is_dir($directory)){@mkdir($directory,0700,true);}@file_put_contents($path,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),LOCK_EX);return$value;}$raw=is_file($path)?@file_get_contents($path):false;$data=$raw===false?null:json_decode($raw,true);return isset($data['at'])&&is_int($data['at'])&&is_array($data['items']??null)?$data:null;}}